"""Convert staged fictional JPEGs to embedded WebP fixtures using Pillow.

Usage: python3 scripts/convert-dune-photos.py /path/to/dune-photos
Only the generated TypeScript data is needed at runtime.
"""
import base64
from io import BytesIO
from pathlib import Path
import sys

from PIL import Image, ImageOps

source = Path(sys.argv[1])
output = Path(__file__).resolve().parents[1] / 'lib' / 'fixture-dune-photos.ts'
lines = [
    '// Staged fictional sites. No people, logos, camera details or location data.',
    '// Generated by scripts/convert-dune-photos.py with Pillow. Do not edit the bytes.',
    'export const dunePhotos = {',
]
for key, filename in [
    ('acBefore', 'ac-before.jpg'), ('acAfter', 'ac-after.jpg'),
    ('leakBefore', 'leak-before.jpg'), ('leakAfter', 'leak-after.jpg'),
]:
    with Image.open(source / filename) as original:
        photo = ImageOps.exif_transpose(original).convert('RGB')
        photo.thumbnail((480, 480), Image.Resampling.LANCZOS)
        # Copy pixels only, so no source metadata can enter the fixture.
        clean = Image.new('RGB', photo.size)
        clean.paste(photo)
        data = BytesIO()
        clean.save(data, format='WEBP', quality=60, method=6)
        raw = data.getvalue()
        if len(raw) >= 40 * 1024:
            raise ValueError(f'{filename} exceeds the fixture size budget')
        encoded = base64.b64encode(raw).decode('ascii')
        lines.append(f"  {key}: {{ width: {clean.width}, height: {clean.height}, bytes: Buffer.from('{encoded}', 'base64') }},")
        print(f'{filename}: {clean.width} x {clean.height}, {len(raw)} bytes')
lines.append('} as const;')
output.write_text('\n'.join(lines) + '\n')
